/** Durable sequencing for a GM-prepared Spellsteal transfer.
 *
 * This engine is not a query handler. Its adapters must enforce active-GM
 * authority, ownership, rank, capacity and protection. Claiming must also
 * suspend the cast's ticks/actions and orphan cleanup until completion or GM
 * review; otherwise an intermediate state could deal damage or be deleted.
 * All writes for this service must use one serialized instance. The claim ID
 * distinguishes competing/replaced receipts; it is generated by the GM.
 *
 * prepare(request): read-only complete plan, or null to refuse.
 * readReceipt(key): durable receipt or null.
 * writeReceipt(key, receipt): persist; never implicitly replay a game write.
 * validate(plan, receipt, {stage, when}): authority and exact expected world
 *   state at this boundary, including postconditions after every game write.
 * perform(stage, plan, receipt): one stage, with its own exact-state checks.
 *
 * Specialized carriers and Regions must already have complete plans before
 * prepare returns. A partial carrier inventory is not an executable plan.
 */
const STAGES = Object.freeze(["holdRecipient", "relocateCarriers", "releaseSource"]);
const identity = value => typeof value === "string" && value.trim().length > 0;
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

export function createSustainTransferDelivery({ prepare, readReceipt, writeReceipt, validate, perform }) {
  if ([prepare, readReceipt, writeReceipt, validate, perform].some(fn => typeof fn !== "function")) {
    throw Error("Sustain transfer requires every delivery adapter");
  }
  let queue = Promise.resolve();
  const uncertain = new Set();
  return function transfer(request) {
    const input = structuredClone(request);
    const run = async () => {
      let key = null;
      let claimed = false;
      try {
        const prepared = await prepare(input);
        if (!prepared || ![prepared.casterUuid, prepared.recipientUuid, prepared.cast, prepared.transactionId].every(identity)
          || prepared.casterUuid === prepared.recipientUuid) return { ok: false, reason: "context" };
        const plan = structuredClone(prepared);
        // Recipient is deliberately absent: stealing the same source cast into
        // a different Mage is still a competing request, not a fresh transfer.
        key = JSON.stringify([plan.casterUuid, plan.cast]);
        if (uncertain.has(key)) return { ok: false, reason: "review" };
        const previous = await readReceipt(key);
        if (previous != null) return { ok: false, reason: previous.version === 1 && previous.state === "done"
          && previous.key === key && previous.casterUuid === plan.casterUuid && previous.cast === plan.cast
          && identity(previous.transactionId) && identity(previous.recipientUuid)
          && same(previous.completed, STAGES) && previous.attempted === null ? "used" : "review" };
        let receipt = { version: 1, key, transactionId: plan.transactionId, casterUuid: plan.casterUuid,
          recipientUuid: plan.recipientUuid, cast: plan.cast, state: "claimed", completed: [], attempted: null,
          plan: structuredClone(plan) };
        const check = async (stage, when) => {
          if (!same(await readReceipt(key), receipt)) return false;
          return await validate(structuredClone(plan), structuredClone(receipt), { stage, when }) === true;
        };
        const save = async next => {
          await writeReceipt(key, structuredClone(next));
          if (!same(await readReceipt(key), next)) throw Error("Transfer receipt write was not confirmed");
          receipt = next;
        };
        if (await validate(structuredClone(plan), null, { stage: null, when: "beforeClaim" }) !== true) {
          return { ok: false, reason: "changed" };
        }
        // Recheck immediately before claiming, after the asynchronous validator.
        if (await readReceipt(key) != null) return { ok: false, reason: "review" };
        claimed = true; // A rejected write may already have persisted the claim.
        await save(receipt);
        for (const stage of STAGES) {
          if (!await check(stage, "before")) throw Error("Transfer state changed");
          await save({ ...receipt, attempted: stage });
          if (!await check(stage, "before")) throw Error("Transfer authority or claim changed");
          await perform(stage, structuredClone(plan), structuredClone(receipt));
          if (!await check(stage, "after")) throw Error("Transfer postcondition not established");
          await save({ ...receipt, completed: [...receipt.completed, stage], attempted: null });
        }
        if (!await check(null, "beforeComplete")) throw Error("Transfer completion state changed");
        await save({ ...receipt, state: "done" });
        return { ok: true, key, transactionId: plan.transactionId };
      } catch {
        // Do not undo, refund, resume or retry an uncertain world write. The
        // receipt preserves the last confirmed stage and the attempted stage.
        if (key && claimed) uncertain.add(key);
        return { ok: false, reason: claimed ? "review" : "context" };
      }
    };
    const result = queue.then(run, run);
    queue = result.catch(() => {});
    return result;
  };
}
